<style>
    .s8-shell{display:grid;gap:32px}.s8-hero{padding:54px 0 30px;border-bottom:1px solid var(--line)}
    .s8-kicker{font-size:12px;font-weight:800;letter-spacing:.18em;color:var(--accent-dark)}
    .s8-hero h1{font-size:clamp(38px,7vw,74px);line-height:1.06;max-width:900px;margin:18px 0}.s8-lead{font-size:clamp(18px,2.4vw,25px);max-width:760px;color:var(--ink)}
    .s8-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:18px}.s8-card{background:#fff;border:1px solid var(--line);border-radius:16px;padding:24px}.s8-card h2,.s8-card h3{margin:8px 0}
    .s8-meta{display:flex;flex-wrap:wrap;gap:10px;color:var(--muted);font-size:13px}.s8-chip{display:inline-flex;padding:5px 10px;border:1px solid var(--line);border-radius:999px;background:#fff}
    .s8-action{border-left:3px solid var(--accent);padding:14px 16px;background:#f8fbfc;margin-top:12px}.s8-action p{margin:6px 0}.s8-toolbar{display:flex;align-items:center;justify-content:space-between;gap:16px;flex-wrap:wrap}
    .s8-button{display:inline-flex;padding:10px 16px;border-radius:999px;background:var(--accent-dark);color:#fff;border:0;font-weight:700;cursor:pointer}.s8-form{display:grid;gap:16px}.s8-form-row{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:16px}.s8-muted{color:var(--muted)}
    @media(max-width:600px){.s8-grid,.s8-form-row{grid-template-columns:1fr}.s8-hero{padding-top:28px}.s8-card{padding:18px}.s8-toolbar{align-items:flex-start}}
</style>
